const modules = import.meta.glob('../assets/icons/*.png', {
  eager: true,
  import: 'default'
}) as Record<string, string>

/**
 * Maps every bundled icon slug (the PNG filename without its extension) to the
 * URL generated by Vite. Keeping the map here means locale files only store a
 * readable `icons/<slug>.png` reference and the build handles hashing.
 */
export const ICONS: Record<string, string> = Object.fromEntries(
  Object.entries(modules).map(([path, url]) => {
    const file = path.split('/').pop() ?? ''
    return [file.replace(/\.png$/i, ''), url]
  })
)

export const iconSlug = (reference?: string): string | undefined => {
  if (!reference) return undefined
  return reference.replace(/^.*\//, '').replace(/\.png$/i, '')
}

export const iconSrc = (reference?: string): string | undefined => {
  const slug = iconSlug(reference)
  return slug ? ICONS[slug] : undefined
}
